SELECT DATE_TRUNC('YEAR', txn_time) AS year_start, DATE_TRUNC('MONTH', txn_time) AS activity_month, CASE WHEN amount >= 3800 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN txn_type = 'FEE' THEN 1 END), 0), 2) AS amount_per_fee, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS duration_min, COUNT(*) FILTER (WHERE merchant = 'Grab') AS grab_rows, SUM(CASE WHEN txn_type = 'FEE' THEN amount ELSE 0 END) AS fee_amount, MIN(txn_time) AS first_seen FROM transactions GROUP BY year_start, activity_month, amount_tier ORDER BY amount_per_fee;
